#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    const long long STEP_LIMIT = 999999LL;
    const long long OVERFLOW_GUARD = 1000000000000000LL; // 1e15
    long long steps = 0;
    long long cur = n;

    while (cur != 1) {
        if (cur > OVERFLOW_GUARD) {
            puts("OVERFLOW_GUARD");
            return 0;
        }
        if ((cur & 1LL) == 0) {
            cur >>= 1;
        } else {
            cur = cur * 3 + 1;
        }
        ++steps;
        if (steps > STEP_LIMIT) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }
    }

    printf("n=%lld steps=%lld\n", n, steps);
    return 0;
}
